css:
body {
        font-family: Arial, sans-serif;
        font-size: 12px;
        margin: 5px;
    }

    .outer-box {
        border: 2px solid #000;
        padding: 5px;
        margin: 5px;
        border-radius: 4px;
    }

    .header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        border-bottom: 1px solid #000;
        padding: 6px;
        margin-bottom: 10px;
    }

    .header img {
        max-height: 25px;
        max-width: 80px;
    }

    .company-details {
        text-align: center;
        font-size: 12px;
        line-height: 1.4;
        flex: 1;
    }

    .compnay-info-name {
        font-size: 20px;
    }

    table {
        border-collapse: collapse;
        width: 100%;
        margin-bottom: 15px;
        font-size: 12px;
    }
    

    table, th, td {
        border: 1px solid #000;
    }

    /*th {*/
    /*    background-color: #ff8000;*/
    /*}*/
    

    th, td {
        padding: 6px;
        text-align: center;
    }

    td {
        text-align: left;
    }

    .label {
        font-weight: bold;
    }
    
    .po {
        text-align: center;
        font-size: 14px;
        font-weight: bold;
        margin: 10px 0;
    }
